// #36c6b2 «בלי חיבור לאינטרנט — מסך הבית, תפילה ותהילים» (оба платформы) — עבר QA 19.11.2026 (подтвердил пользователь).
//   Факт: после открытия с интернетом → режим полёта → холодный старт: главная показывает еврейскую дату и время молитвы и баннер
//   «אין חיבור לאינטרנט. מוצג מה שכבר נשמר במכשיר.»; «תפילות» → «פתיחת שחרית…» открывает текст (есть «מודה אני»); глава תהילים, которую
//   не открывали (поиск «חיפוש לפי מספר פרק או מילים» → 121 или 137) открывается с текстом.
//   ВНИМАНИЕ: экран «תהילים / פרקי אבות» лежит во вкладке «ברכות» (корона), а во вкладке «תהילים» — список ברכות: это норма по Figma (#8060ad);
//   openTehilimScreen() ищет в обеих вкладках.
// СЕТЬ (авиарежим) ВЫКЛЮЧАЕТ И ВКЛЮЧАЕТ ЧЕЛОВЕК — QA_OFFLINE_MANUAL=1, иначе skip (образец qa-2510 q-14). Глава: QA_UNOPENED_TEHILIM (121 по умолчанию, или 137;
// глава, которую на этом телефоне не открывали). Файл serial: шаги зависят друг от друга. Кейс: .qa/tests/phone/qa-2026-11-19.md (Q19-04a…c).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches } from '../../helpers/ui.ts';
import { skipWith, shown, searchField, hebNum } from '../_lib/app-0710.ts';
import { goHome, waitHuman, openCatalogPrayer, nodes, stripNikud, MANUAL_WAIT } from '../_lib/readiness-1910.ts';
import { homeHebrewDate } from '../_lib/app-1310b.ts';
import { coldStart, offlineBannerShown, openTehilimScreen, segment, OFF_BANNER, PH_TEHILIM } from '../_lib/app-2510.ts';
import { homeHasPrayerTime, saveShot, TEHILIM_UNOPENED } from '../_lib/app-1911.ts';

const NIKUD_RE = '.*[\\u05B0-\\u05C7].*';
const MODEH = 'מודה אני';
const PRAYER = 'שחרית';

describe('19.11 — без интернета: главная, молитва, תהילים (#36c6b2)', function () {
  before(function () {
    if (process.env.QA_OFFLINE_MANUAL !== '1') skipWith(this, 'сеть выключает человек — запуск с QA_OFFLINE_MANUAL=1 и человеком у телефона');
  });

  it('Q19-04a С интернетом: холодный старт, главная с еврейской датой и временем молитвы, открыть «שחרית» (текст сохранится в кэше); без баннера #36c6b2 @manual-check @prod-safe', async function () {
    this.timeout(600000);
    await coldStart('онлайн старт');
    expect(await offlineBannerShown()).toBe(false);
    const heb = await homeHebrewDate();
    console.log(`[Q-38] онлайн: еврейская дата «${heb.full}»`);
    expect(await homeHasPrayerTime()).toBe(true);
    await openCatalogPrayer(PRAYER);
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 20000 });
    await goHome();
  });

  it('Q19-04b Режим полёта (человек) → холодный старт: главная показывает еврейскую дату, время молитвы и баннер «אין חיבור לאינטרנט. מוצג מה שכבר נשמר במכשיר.» #36c6b2 @manual-check @prod-safe', async function () {
    this.timeout(MANUAL_WAIT + 600000);
    await waitHuman('ВКЛЮЧИТЕ режим полёта (Wi‑Fi и сотовая выкл.), приложение не закрывать. Тест ждёт баннер «אין חיבור לאינטרנט».', offlineBannerShown);
    await coldStart('офлайн старт');
    await expect(byTextContains(OFF_BANNER)).toBeExisting({ wait: 20000 });
    const heb = await homeHebrewDate();
    console.log(`[Q-38] офлайн: еврейская дата «${heb.full}»`);
    expect(heb.full.length).toBeGreaterThan(0);
    expect(await homeHasPrayerTime()).toBe(true);
    await saveShot('q38-offline-home.png');
  });

  it('Q19-04c Офлайн: «תפילות» → «פתיחת שחרית…» открывает текст с «מודה אני» #36c6b2 @manual-check @prod-safe', async function () {
    this.timeout(300000);
    await openCatalogPrayer(PRAYER);
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 30000 });
    await driver.waitUntil(async () => (await nodes()).some((n) => stripNikud(n.label).includes(MODEH)),
      { timeout: 20000, interval: 1000, timeoutMsg: `в тексте «${PRAYER}» нет «${MODEH}» (огласовки сняты)` });
    await saveShot('q38-offline-shacharit.png');
    await goHome();
  });

  it('Q19-04d Офлайн: глава תהילים, которую не открывали (121 / 137), открывается с текстом — поиск «חיפוש לפי מספר פרק או מילים» #36c6b2 @manual-check @prod-safe', async function () {
    this.timeout(300000);
    const where = await openTehilimScreen();            // «ברכות» (корона) — норма по Figma #8060ad; «תהילים» — запасной вариант
    console.log(`[Q-38] экран «תהילים / פרקי אבות» найден во вкладке «${where}»`);
    await segment('תהילים');
    const f = (await searchField()) as unknown as WebdriverIO.Element;
    await f.clearValue();
    await f.setValue(String(TEHILIM_UNOPENED));
    if (driver.isIOS) await driver.execute('mobile: hideKeyboard', {}).catch(() => {});
    await (await byText(hebNum(TEHILIM_UNOPENED))).click();
    await (await byText(`תהילים ${hebNum(TEHILIM_UNOPENED)}`)).waitForExist({ timeout: 30000 });
    await expect(byTextMatches(NIKUD_RE)).toBeExisting({ wait: 30000 });
    expect(await shown(byTextContains('הקטע אינו זמין כרגע.'))).toBe(false);
    await saveShot('q38-offline-tehilim.png');
    console.log(`[Q-38] placeholder поиска: «${PH_TEHILIM}»`);
    await goHome();
  });

  after(async function () {
    this.timeout(MANUAL_WAIT);
    if (process.env.QA_OFFLINE_MANUAL !== '1') return;
    if (await offlineBannerShown().catch(() => false)) {
      await waitHuman('тест закончился с выключенной сетью — ВЫКЛЮЧИТЕ режим полёта', async () => !(await offlineBannerShown()));
    }
  });
});
